python -c "
import sys
sys.argv = ['glom', '--spec-format=python-full', 'T[\"name\"]', '{\"name\": \"test\", \"value\": 42}']

# Let's add some debug prints to cli.py
from glom import *
from glom.cli import mw_handle_target, _error, main

# Monkey-patch the middleware temporarily
import glom.cli as cli_module

original_mw_get_target = cli_module.mw_get_target

def patched_mw_get_target(next_, posargs_, target_file, target_format, spec_file, spec_format):
    print('PATCHED: posargs_ =', repr(posargs_))
    print('PATCHED: spec_format =', repr(spec_format))

    spec_text, target_text = None, None
    if len(posargs_) == 2:
        spec_text, target_text = posargs_
    elif len(posargs_) == 1:
        spec_text, target_text = posargs_[0], None

    print('PATCHED: spec_text =', repr(spec_text))
    print('PATCHED: target_text =', repr(target_text))

    # Now do the actual parsing
    if not spec_text:
        spec = Path()
    elif spec_format == 'python':
        if spec_text[0] not in ('\"', \"'\", '[', '{', '('):
            spec_text = repr(spec_text)
        spec = ast.literal_eval(spec_text)
    elif spec_format == 'json':
        spec = json.loads(spec_text)
    elif spec_format == 'python-full':
        try:
            spec = eval(spec_text, {'__builtins__': {}}, {
                'T': T, 'S': S, 'Path': Path, 'Spec': Spec,
                'Literal': Literal, 'Coalesce': Coalesce,
                'Inspect': Inspect, 'Call': Call, 'Check': Check,
                'OMIT': OMIT, 'SKIP': SKIP, 'STOP': STOP,
                'Auto': Auto, 'ROOT': ROOT, 'Let': Let,
                'Iter': Iter, 'Fill': Fill, 'Invoke': Invoke,
            })
            print('PATCHED: eval result =', repr(spec))
        except Exception as e:
            _error('could not parse spec as python-full expression: %s' % e)
    else:
        _error('expected spec-format to be one of python, python-full or json')

    if target_text and target_file:
        _error('expected target file or target argument, not both')
    elif target_text == '-' or target_file == '-':
        with sys.stdin as f:
            target_text = f.read()
    elif target_file:
        try:
            target_text = open(target_file, 'r').read()
        except IOError as ose:
            _error('could not read target file %r, got: %s' % (spec_file, ose))
    elif not target_text and not os.isatty(sys.stdin.fileno()):
        with sys.stdin as f:
            target_text = f.read()

    target = mw_handle_target(target_text, target_format)

    return next_(spec=spec, target=target)

# Replace the middleware
cli_module.mw_get_target.__middleware__ = patched_mw_get_target
" 2>&1 | head -30
